/* Student Debt Dashboard — Analytics UI (scope .std-dash-root) */

.page-wrapper .page-content .std-dash-root {
    --std-primary: #4B6CB7;
    --std-primary-dark: #3d5a9a;
    --std-success: #22C55E;
    --std-warning: #F59E0B;
    --std-danger: #EF4444;
    --std-info: #0EA5E9;
    --std-indigo: #6366F1;
    --std-bg: #F8FAFC;
    --std-card: #FFFFFF;
    --std-text: #0F172A;
    --std-text-muted: #64748B;
    --std-border: #E2E8F0;
    --std-radius: 12px;
    --std-shadow: 0 1px 3px rgba(15, 23, 42, 0.06), 0 4px 16px rgba(15, 23, 42, 0.04);
    --std-shadow-hover: 0 4px 12px rgba(15, 23, 42, 0.08), 0 12px 32px rgba(75, 108, 183, 0.12);
    background: var(--std-bg);
    margin: -1rem -1.25rem;
    padding: 1rem 1.25rem 1.5rem;
    min-height: calc(100vh - 120px);
}

.page-wrapper .page-content .std-dash-container {
    max-width: 1600px;
}

/* Page header */
.page-wrapper .page-content .std-dash-page-row {
    margin-bottom: 1rem;
}

.page-wrapper .page-content .std-dash-page-title {
    font-size: 1.35rem;
    font-weight: 700;
    color: var(--std-text);
    display: flex;
    align-items: center;
    gap: 0.65rem;
}

.page-wrapper .page-content .std-dash-page-title-icon {
    width: 40px;
    height: 40px;
    border-radius: 10px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-size: 1.1rem;
    background: rgba(75, 108, 183, 0.12);
    color: var(--std-primary);
}

.page-wrapper .page-content .std-dash-page-subtitle {
    font-size: 0.85rem;
    color: var(--std-text-muted);
    padding-left: 3.05rem;
}

.page-wrapper .page-content .std-dash-breadcrumb {
    font-size: 0.82rem;
}

.page-wrapper .page-content .std-dash-breadcrumb a {
    color: var(--std-primary);
    text-decoration: none;
}

/* Cards */
.page-wrapper .page-content .std-dash-root .std-dash-card {
    border: 1px solid var(--std-border);
    border-radius: var(--std-radius);
    box-shadow: var(--std-shadow);
    background: var(--std-card);
    transition: box-shadow 0.25s ease, transform 0.25s ease;
}

.page-wrapper .page-content .std-dash-root .std-dash-card:hover {
    box-shadow: var(--std-shadow-hover);
}

.page-wrapper .page-content .std-dash-root .std-dash-card-header {
    padding: 1rem 1.25rem 0.35rem;
    border-bottom: none;
    background: transparent;
}

.page-wrapper .page-content .std-dash-root .std-dash-card-title {
    font-size: 0.95rem;
    font-weight: 600;
    color: var(--std-text);
}

.page-wrapper .page-content .std-dash-root .std-dash-card-title i {
    color: var(--std-primary);
}

.page-wrapper .page-content .std-dash-root .std-dash-card-subtitle {
    font-size: 0.78rem;
    color: var(--std-text-muted);
    margin-top: 0.15rem;
}

.page-wrapper .page-content .std-dash-root .std-dash-card-body {
    padding: 0.5rem 1.25rem 1.15rem;
}

.page-wrapper .page-content .std-dash-root .std-dash-alert {
    border-radius: var(--std-radius);
}

/* Filter bar */
.page-wrapper .page-content .std-dash-filter-card {
    padding: 0.85rem 1.15rem;
    margin-bottom: 1rem;
}

.page-wrapper .page-content .std-dash-filter-bar {
    display: flex;
    flex-wrap: wrap;
    align-items: flex-end;
    justify-content: space-between;
    gap: 0.75rem 1rem;
}

.page-wrapper .page-content .std-dash-filter-grid {
    display: flex;
    flex-wrap: wrap;
    align-items: flex-end;
    gap: 0.5rem 0.65rem;
    flex: 1 1 auto;
    min-width: 0;
}

.page-wrapper .page-content .std-dash-filter-grid > .row,
.page-wrapper .page-content .std-dash-filter-grid .std-dash-year-sem-filter > .row {
    display: contents;
}

.page-wrapper .page-content .std-dash-filter-grid [class*="col-"] {
    flex: 0 0 auto;
    width: auto;
    min-width: 130px;
    max-width: 170px;
    padding: 0;
}

.page-wrapper .page-content .std-dash-filter-grid .form-label {
    font-size: 0.7rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: var(--std-text-muted);
    margin-bottom: 0.2rem;
    white-space: nowrap;
}

.page-wrapper .page-content .std-dash-filter-grid .scs-dash-filter-icon {
    color: var(--std-primary);
    font-size: 0.8rem;
}

.page-wrapper .page-content .std-dash-filter-grid .form-select {
    font-size: 0.82rem;
    border-color: var(--std-border);
    border-radius: 8px;
    padding: 0.35rem 1.75rem 0.35rem 0.65rem;
    color: var(--std-text);
    height: 34px;
}

.page-wrapper .page-content .std-dash-filter-grid .form-select:focus {
    border-color: var(--std-primary);
    box-shadow: 0 0 0 0.2rem rgba(75, 108, 183, 0.15);
}

.page-wrapper .page-content .std-dash-year-sem-filter > .row > div:nth-child(3) {
    display: none;
}

.page-wrapper .page-content .std-dash-filter-toolbar {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: flex-end;
    gap: 0.65rem 1rem;
    flex-shrink: 0;
}

.page-wrapper .page-content .std-dash-update {
    font-size: 0.78rem;
    color: var(--std-text-muted);
    white-space: nowrap;
}

.page-wrapper .page-content .std-dash-update strong {
    color: var(--std-text);
    font-weight: 600;
}

.page-wrapper .page-content .std-dash-filter-btns {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem;
}

.page-wrapper .page-content .std-dash-btn-primary {
    background: var(--std-primary);
    border-color: var(--std-primary);
    border-radius: 8px;
    font-size: 0.82rem;
    font-weight: 600;
    padding: 0.38rem 1rem;
    height: 34px;
    line-height: 1.2;
}

.page-wrapper .page-content .std-dash-btn-primary:hover,
.page-wrapper .page-content .std-dash-btn-primary:focus {
    background: var(--std-primary-dark);
    border-color: var(--std-primary-dark);
}

.page-wrapper .page-content .std-dash-btn-outline {
    border-radius: 8px;
    font-size: 0.82rem;
    font-weight: 500;
    padding: 0.38rem 1rem;
    height: 34px;
    line-height: 1.2;
    border-color: var(--std-border);
    color: var(--std-text-muted);
}

.page-wrapper .page-content .std-dash-btn-outline:hover,
.page-wrapper .page-content .std-dash-btn-outline:focus {
    border-color: #94a3b8;
    color: var(--std-text);
    background: #fff;
}

/* KPI grid */
.page-wrapper .page-content .std-dash-kpi-grid {
    display: grid;
    grid-template-columns: repeat(7, 1fr);
    gap: 0.85rem;
    margin-bottom: 1rem;
}

.page-wrapper .page-content .std-dash-kpi {
    padding: 1rem 1.1rem;
    cursor: default;
    position: relative;
    overflow: hidden;
}

.page-wrapper .page-content .std-dash-kpi::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    border-radius: var(--std-radius) var(--std-radius) 0 0;
    opacity: 0.85;
}

.page-wrapper .page-content .std-dash-kpi-danger::before { background: var(--std-danger); }
.page-wrapper .page-content .std-dash-kpi-neutral::before { background: var(--std-primary); }
.page-wrapper .page-content .std-dash-kpi-blue::before { background: var(--std-info); }
.page-wrapper .page-content .std-dash-kpi-success::before { background: var(--std-success); }
.page-wrapper .page-content .std-dash-kpi-warning::before { background: var(--std-warning); }
.page-wrapper .page-content .std-dash-kpi-indigo::before { background: var(--std-indigo); }
.page-wrapper .page-content .std-dash-kpi-indigo-alt::before { background: #818CF8; }

.page-wrapper .page-content .std-dash-kpi:hover {
    transform: translateY(-3px);
}

.page-wrapper .page-content .std-dash-kpi-body {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 0.5rem;
}

.page-wrapper .page-content .std-dash-kpi-content {
    min-width: 0;
    flex: 1;
}

.page-wrapper .page-content .std-dash-root .sch-dash-kpi-value {
    font-size: 1.25rem;
    font-weight: 700;
    color: var(--std-text);
    line-height: 1.25;
    word-break: break-word;
}

.page-wrapper .page-content .std-dash-kpi-blue .sch-dash-kpi-value { color: var(--std-info); }
.page-wrapper .page-content .std-dash-kpi-success .sch-dash-kpi-value { color: var(--std-success); }
.page-wrapper .page-content .std-dash-kpi-warning .sch-dash-kpi-value { color: var(--std-warning); }
.page-wrapper .page-content .std-dash-kpi-danger .sch-dash-kpi-value { color: var(--std-danger); }
.page-wrapper .page-content .std-dash-kpi-indigo .sch-dash-kpi-value,
.page-wrapper .page-content .std-dash-kpi-indigo-alt .sch-dash-kpi-value { color: var(--std-indigo); }

.page-wrapper .page-content .std-dash-root .sch-dash-kpi-label {
    font-size: 0.72rem;
    color: var(--std-text-muted);
    font-weight: 500;
    margin-top: 0.25rem;
    line-height: 1.3;
}

.page-wrapper .page-content .std-dash-kpi-icon {
    width: 52px;
    height: 52px;
    border-radius: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.5rem;
    flex-shrink: 0;
    opacity: 0.9;
}

.page-wrapper .page-content .std-dash-kpi-danger .std-dash-kpi-icon {
    background: rgba(239, 68, 68, 0.12);
    color: var(--std-danger);
}

.page-wrapper .page-content .std-dash-kpi-neutral .std-dash-kpi-icon {
    background: rgba(75, 108, 183, 0.12);
    color: var(--std-primary);
}

.page-wrapper .page-content .std-dash-kpi-blue .std-dash-kpi-icon {
    background: rgba(14, 165, 233, 0.12);
    color: var(--std-info);
}

.page-wrapper .page-content .std-dash-kpi-success .std-dash-kpi-icon {
    background: rgba(34, 197, 94, 0.12);
    color: var(--std-success);
}

.page-wrapper .page-content .std-dash-kpi-warning .std-dash-kpi-icon {
    background: rgba(245, 158, 11, 0.12);
    color: var(--std-warning);
}

.page-wrapper .page-content .std-dash-kpi-indigo .std-dash-kpi-icon,
.page-wrapper .page-content .std-dash-kpi-indigo-alt .std-dash-kpi-icon {
    background: rgba(99, 102, 241, 0.12);
    color: var(--std-indigo);
}

/* Chart rows */
.page-wrapper .page-content .std-dash-chart-row {
    margin-bottom: 1rem;
}

.page-wrapper .page-content .std-dash-chart-card .std-dash-card-header .std-dash-fs-btn {
    flex-shrink: 0;
    margin-left: 0.5rem;
    min-width: 34px;
    padding: 0.35rem 0.55rem !important;
    border-color: var(--std-border) !important;
    color: var(--std-text-muted) !important;
    background: #fff !important;
    opacity: 1 !important;
    border-radius: 8px;
}

.page-wrapper .page-content .std-dash-chart-card .std-dash-card-header .std-dash-fs-btn:hover,
.page-wrapper .page-content .std-dash-chart-card .std-dash-card-header .std-dash-fs-btn:focus {
    border-color: #94a3b8 !important;
    color: var(--std-text) !important;
    background: var(--std-bg) !important;
}

.page-wrapper .page-content .std-dash-chart-card .std-dash-card-header .std-dash-fs-btn.std-dash-fs-btn-inactive {
    opacity: 0.45 !important;
    cursor: not-allowed;
}

.page-wrapper .page-content .std-dash-chart-wrap {
    min-height: 340px;
    overflow: hidden;
}

.page-wrapper .page-content .std-dash-chart-wrap > div {
    width: 100%;
    max-width: 100%;
}

.page-wrapper .page-content .std-dash-area-wrap {
    min-height: 380px;
}

.page-wrapper .page-content .std-dash-chart-hero .std-dash-card-body {
    padding-top: 0.25rem;
}

.page-wrapper .page-content .std-dash-chart-empty {
    min-height: 300px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--std-text-muted);
    font-size: 0.88rem;
}

.page-wrapper .page-content .std-dash-chart-scroll-wrap {
    width: 100%;
    overflow-y: auto;
    overflow-x: hidden;
}

.page-wrapper .page-content .std-dash-chart-note {
    font-size: 0.76rem;
    color: var(--std-text-muted);
    margin-bottom: 0.4rem;
}

.page-wrapper .page-content .std-dash-ratio-wrap {
    min-height: 340px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.page-wrapper .page-content .std-dash-treemap-wrap {
    min-height: 340px;
}

.page-wrapper .page-content .std-dash-trend-wrap {
    min-height: 340px;
}

.page-wrapper .page-content .std-dash-trend-card .std-dash-card-body {
    padding-top: 0.25rem;
}

/* Fullscreen */
.std-dash-fullscreen {
    position: fixed;
    inset: 0;
    z-index: 3000;
    background: var(--std-bg, #F8FAFC);
    display: flex;
    flex-direction: column;
}

.std-dash-fullscreen.d-none {
    display: none !important;
}

.std-dash-fullscreen-toolbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.75rem 1.25rem;
    background: #fff;
    border-bottom: 1px solid var(--std-border, #E2E8F0);
    box-shadow: 0 2px 8px rgba(15, 23, 42, 0.06);
}

.std-dash-fullscreen-body {
    flex: 1;
    padding: 1rem 1.25rem;
    min-height: 0;
    overflow: hidden;
}

.std-dash-fullscreen-chart-wrap {
    width: 100%;
    height: 100%;
    background: #fff;
    border-radius: var(--std-radius, 12px);
    border: 1px solid var(--std-border, #E2E8F0);
    padding: 0.75rem;
    box-shadow: var(--std-shadow);
}

.std-dash-fullscreen-chart-wrap > div {
    width: 100%;
    height: 100%;
}

.std-dash-fullscreen-horizontal .std-dash-fullscreen-body {
    overflow-y: auto;
    overflow-x: hidden;
}

.std-dash-fullscreen-horizontal .std-dash-fullscreen-chart-wrap {
    overflow: auto;
    min-height: calc(100vh - 88px);
}

.std-dash-fullscreen-line .std-dash-fullscreen-body {
    overflow: hidden;
}

.std-dash-fullscreen-line .std-dash-fullscreen-chart-wrap {
    overflow: hidden;
    min-height: calc(100vh - 88px);
}

.std-dash-fullscreen-center .std-dash-fullscreen-body {
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
}

.std-dash-fullscreen-center .std-dash-fullscreen-chart-wrap {
    min-height: auto;
    max-width: 720px;
    margin: 0 auto;
    height: auto;
}

.std-dash-fullscreen-area .std-dash-fullscreen-body {
    overflow: hidden;
}

.std-dash-fullscreen-area .std-dash-fullscreen-chart-wrap {
    overflow: hidden;
    min-height: calc(100vh - 88px);
}

/* Responsive */
@media (max-width: 1399.98px) {
    .page-wrapper .page-content .std-dash-kpi-grid {
        grid-template-columns: repeat(4, 1fr);
    }
}

@media (max-width: 991.98px) {
    .page-wrapper .page-content .std-dash-kpi-grid {
        grid-template-columns: repeat(3, 1fr);
    }

    .page-wrapper .page-content .std-dash-filter-grid [class*="col-"] {
        min-width: 120px;
        max-width: 160px;
    }

    .page-wrapper .page-content .std-dash-page-subtitle {
        padding-left: 0;
    }
}

@media (max-width: 767.98px) {
    .page-wrapper .page-content .std-dash-root {
        margin: -0.5rem -0.75rem;
        padding: 0.75rem;
    }

    .page-wrapper .page-content .std-dash-kpi-grid {
        grid-template-columns: repeat(2, 1fr);
        gap: 0.65rem;
    }

    .page-wrapper .page-content .std-dash-root .sch-dash-kpi-value {
        font-size: 1.05rem;
    }

    .page-wrapper .page-content .std-dash-kpi-icon {
        width: 42px;
        height: 42px;
        font-size: 1.2rem;
    }

    .page-wrapper .page-content .std-dash-filter-bar {
        flex-direction: column;
        align-items: stretch;
    }

    .page-wrapper .page-content .std-dash-filter-grid [class*="col-"] {
        min-width: calc(50% - 0.35rem);
        max-width: none;
        flex: 1 1 calc(50% - 0.35rem);
    }

    .page-wrapper .page-content .std-dash-filter-toolbar {
        justify-content: space-between;
        width: 100%;
    }

    .page-wrapper .page-content .std-dash-area-wrap {
        min-height: 300px;
    }

    .page-wrapper .page-content .std-dash-chart-wrap,
    .page-wrapper .page-content .std-dash-ratio-wrap,
    .page-wrapper .page-content .std-dash-treemap-wrap,
    .page-wrapper .page-content .std-dash-trend-wrap {
        min-height: 280px;
    }
}

@media (max-width: 479.98px) {
    .page-wrapper .page-content .std-dash-kpi-grid {
        grid-template-columns: 1fr;
    }

    .page-wrapper .page-content .std-dash-filter-grid [class*="col-"] {
        min-width: 100%;
        flex: 1 1 100%;
    }

    .page-wrapper .page-content .std-dash-filter-toolbar {
        flex-direction: column;
        align-items: stretch;
    }

    .page-wrapper .page-content .std-dash-filter-btns {
        width: 100%;
    }

    .page-wrapper .page-content .std-dash-filter-btns .btn {
        flex: 1;
    }
}

/**
 * Dashboard Công nợ lớp — Analytics UI
 * Load: ACC_CongNoHocSinh_Dashboard_Web -> StudentDebtDashboardApi.ashx -> ApexCharts
 */
(function () {
    "use strict";

    var API_URL = "/Dashboards/API/StudentDebtDashboardApi.ashx";
    var PRIMARY = "#4B6CB7";
    var SUCCESS = "#22C55E";
    var WARNING = "#F59E0B";
    var DANGER = "#EF4444";
    var INFO = "#0EA5E9";
    var INDIGO = "#6366F1";
    var MUTED = "#64748B";
    var CARD_PREVIEW_LIMIT = 10;
    var CARD_CHART_MAX_HEIGHT = 360;

    var chartInstances = {};
    var lastPayload = null;
    var eventsBound = false;
    var filterConfig = window.stdDashFilterConfig || {};
    var fullscreenStates = {};

    var baseChartOpts = {
        fontFamily: "inherit",
        foreColor: "#475569",
        toolbar: { show: false },
        width: "100%"
    };

    function getEl(id) {
        return document.getElementById(id);
    }

    function formatNumber(val) {
        var num = parseFloat(val);
        if (isNaN(num)) {
            return "0";
        }
        return Math.round(num).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ".");
    }

    function formatMoney(val) {
        return formatNumber(val) + " đ";
    }

    function formatPercent(val) {
        var num = parseFloat(val);
        if (isNaN(num)) {
            return "0%";
        }
        return num.toFixed(1).replace(".", ",") + "%";
    }

    function showState(state) {
        var loading = getEl("stdDashStateLoading");
        var error = getEl("stdDashStateError");
        var empty = getEl("stdDashStateEmpty");
        var content = getEl("stdDashContent");
        if (loading) {
            loading.className = state === "loading" ? "std-dash-state" : "std-dash-state d-none";
        }
        if (error) {
            error.className = state === "error" ? "std-dash-state" : "std-dash-state d-none";
        }
        if (empty) {
            empty.className = state === "empty" ? "std-dash-state" : "std-dash-state d-none";
        }
        if (content) {
            content.style.display = (state === "ready" || state === "empty") ? "" : "none";
        }
    }

    function setErrorMessage(message) {
        var el = getEl("stdDashErrorMessage");
        if (el) {
            el.textContent = message || "Có lỗi xảy ra.";
        }
    }

    function postJson(payload, callback) {
        var xhr = new XMLHttpRequest();
        xhr.open("POST", API_URL, true);
        xhr.setRequestHeader("Content-Type", "application/json; charset=utf-8");
        xhr.onreadystatechange = function () {
            if (xhr.readyState !== 4) {
                return;
            }
            if (xhr.status !== 200) {
                callback(false, "Không kết nối được API dashboard (HTTP " + xhr.status + ").", null);
                return;
            }
            var response = null;
            try {
                response = JSON.parse(xhr.responseText);
            } catch (e) {
                callback(false, "Phản hồi không hợp lệ từ máy chủ.", null);
                return;
            }
            if (!response || !response.success) {
                callback(false, response && response.message ? response.message : "Không tải được dữ liệu.", null);
                return;
            }
            callback(true, "", response.data);
        };
        xhr.onerror = function () {
            callback(false, "Lỗi mạng khi gọi API dashboard.", null);
        };
        xhr.send(JSON.stringify(payload));
    }

    function getSelectValue(clientId) {
        if (!clientId) {
            return "";
        }
        var el = document.getElementById(clientId);
        return el ? el.value : "";
    }

    function readFilters() {
        filterConfig = window.stdDashFilterConfig || filterConfig || {};
        return {
            yearId: getSelectValue(filterConfig.yearId),
            semester: getSelectValue(filterConfig.semesterId),
            scienceId: getSelectValue(filterConfig.scienceId),
            courseId: getSelectValue(filterConfig.courseId),
            classId: getSelectValue(filterConfig.classId)
        };
    }

    function isFilterValueActive(val) {
        return val !== null && val !== undefined && val !== "" && val !== "0" && val !== "-1";
    }

    function validateFilters(filters) {
        if (!isFilterValueActive(filters.yearId)) {
            return "Vui lòng chọn Năm học.";
        }
        if (!isFilterValueActive(filters.semester)) {
            return "Vui lòng chọn Học kỳ.";
        }
        return "";
