    function sliceTopData(rows, labelField, valueField, limit) {
        var pairs = [];
        var i;
        for (i = 0; i < rows.length; i++) {
            pairs.push({
                label: rows[i][labelField] || ("Mục " + (i + 1)),
                value: rows[i][valueField] || 0
            });
        }
        pairs.sort(function (a, b) {
            return (b.value || 0) - (a.value || 0);
        });
        if (limit && pairs.length > limit) {
            pairs = pairs.slice(0, limit);
        }
        var result = { labels: [], series: [], total: rows.length };
        for (i = 0; i < pairs.length; i++) {
            result.labels.push(pairs[i].label);
            result.series.push(pairs[i].value);
        }
        return result;
    }

    function sliceBestCollectionData(rows, limit) {
        var pairs = [];
        var i;
        var plan;
        var receipt;
        var rate;
        for (i = 0; i < rows.length; i++) {
            plan = rows[i].PlanMoney || 0;
            receipt = rows[i].ReceiptMoney || 0;
            if (plan <= 0) {
                continue;
            }
            rate = receipt * 100.0 / plan;
            pairs.push({
                label: rows[i].ClassName || ("Lớp " + (i + 1)),
                value: rate,
                receipt: receipt,
                plan: plan
            });
        }
        pairs.sort(function (a, b) {
            return (b.value || 0) - (a.value || 0);
        });
        if (limit && pairs.length > limit) {
            pairs = pairs.slice(0, limit);
        }
        var result = { labels: [], series: [], total: pairs.length };
        for (i = 0; i < pairs.length; i++) {
            result.labels.push(pairs[i].label);
            result.series.push(Math.round(pairs[i].value * 10) / 10);
        }
        return result;
    }

