        var remainVal = row.RemainMoney || 0;
        renderChart("#stdDashChartRatio", buildDonutOptions(receiptVal, remainVal), "stdDashChartRatioEmpty");
        registerFullscreen("ratio", "Tỷ lệ đã thu / còn nợ", function () {
            return buildDonutOptions(receiptVal, remainVal);
        }, "center");
    }

    function renderTrendChart(rows) {
        var labels = [];
        var receiptSeries = [];
        var i;

        rows = rows || [];
        for (i = 0; i < rows.length; i++) {
            labels.push(rows[i].SegmentLabel || ("Đợt " + (i + 1)));
            receiptSeries.push(rows[i].ReceiptMoney || 0);
        }

        if (labels.length === 0) {
            destroyChart("#stdDashChartTrend");
            toggleChartEmpty("#stdDashChartTrend", "stdDashChartTrendEmpty", true);
            delete fullscreenStates.trend;
            return;
        }

        toggleChartEmpty("#stdDashChartTrend", "stdDashChartTrendEmpty", false);
        renderChart("#stdDashChartTrend", buildReceiptTrendOptions(
            labels,
            receiptSeries,
            340,
            false
        ), "stdDashChartTrendEmpty");

        registerFullscreen("trend", "Xu hướng thu học phí", function () {
            var fsHeight = Math.max(window.innerHeight - 140, 420);
            return buildReceiptTrendOptions(labels, receiptSeries, fsHeight, true);
        }, "line");
    }

    function renderAllCharts(data) {
        resetFullscreenButtons();
        renderKpi(data);
        renderMonthlyAreaChart(data.trendBySegment || []);
        renderDebtBarChart({
            rows: data.byClass || [],
            labelField: "ClassName",
            valueField: "RemainMoney",
            chartId: "#stdDashChartByClass",
            emptyId: "stdDashChartByClassEmpty",
            scrollId: "stdDashByClassScroll",
            noteId: "stdDashByClassNote",
            fsKey: "byClass",
            seriesName: "Còn nợ",
            title: "Top 10 lớp có công nợ cao nhất",
            colors: [DANGER, "#dc2626", WARNING, "#f97316", PRIMARY, INFO, INDIGO, "#9333ea", "#0891b2", "#ca8a04"]
        });
        renderRatioChart(data.ratio || []);
        renderScienceStackedChart(data.byScience || []);
        renderTrendChart(data.trendBySegment || []);
        renderCourseTreemap(data.byCourse || []);
        renderBestClassChart(data.byClass || []);
    }

    function hasData(data) {
        var summary = (data.summary && data.summary.length > 0) ? data.summary[0] : null;
        if (!summary) {
            return false;
        }
        if ((summary.TotalClassCount || 0) > 0) {
            return true;
        }
        if ((summary.TotalPlanMoney || 0) > 0 || (summary.TotalReceiptMoney || 0) > 0) {
            return true;
        }
        return false;
    }

    function loadDashboardData() {
        var filters = readFilters();
        var validationMessage = validateFilters(filters);
        if (validationMessage !== "") {
            setErrorMessage(validationMessage);
            showState("error");
            return;
        }
        showState("loading");
        postJson({
            action: "data",
            yearId: filters.yearId,
            semester: filters.semester,
            scienceId: filters.scienceId,
            courseId: filters.courseId,
            classId: filters.classId
        }, function (success, message, data) {
            if (!success) {
                setErrorMessage(message);
                showState("error");
                return;
            }
            lastPayload = data;
            var updateEl = getEl("stdDashUpdateTime");
            if (updateEl && data.updatedAt) {
                updateEl.textContent = data.updatedAt;
            }
            if (!hasData(data)) {
                showState("empty");
                return;
            }
            showState("ready");
            renderAllCharts(data);
        });
    }

    function openFullscreen(key) {
        var state = fullscreenStates[key];
        var overlay = getEl("stdDashFullscreenOverlay");
        var titleEl = getEl("stdDashFullscreenTitle");
        var chartWrap = getEl("stdDashFullscreenChartWrap");
        var options;
        if (!state || !overlay || !state.optionsBuilder) {
            return;
        }
        if (overlay.parentNode !== document.body) {
            document.body.appendChild(overlay);
        }
        if (titleEl) {
            titleEl.textContent = state.title || "Biểu đồ chi tiết";
        }
        options = state.optionsBuilder();
        if (chartWrap && options && options.chart) {
            chartWrap.style.height = options.chart.height + "px";
        }
        renderChart("#stdDashChartFullscreen", options, null);
        if (state.layoutMode === "line") {
            overlay.className = "std-dash-fullscreen std-dash-fullscreen-line";
        } else if (state.layoutMode === "area") {
            overlay.className = "std-dash-fullscreen std-dash-fullscreen-area";
        } else if (state.layoutMode === "center") {
            overlay.className = "std-dash-fullscreen std-dash-fullscreen-center";
        } else {
            overlay.className = "std-dash-fullscreen std-dash-fullscreen-horizontal";
        }
        document.body.style.overflow = "hidden";
        if (chartInstances["stdDashChartFullscreen"]) {
            chartInstances["stdDashChartFullscreen"].windowResizeHandler();
        }
    }

    function closeFullscreen() {
        var overlay = getEl("stdDashFullscreenOverlay");
        var chartWrap = getEl("stdDashFullscreenChartWrap");
        if (!overlay) {
            return;
        }
        overlay.className = "std-dash-fullscreen d-none";
        document.body.style.overflow = "";
        destroyChart("#stdDashChartFullscreen");
        if (chartWrap) {
            chartWrap.style.height = "";
        }
    }

    function bindEvents() {
        if (eventsBound) {
            return;
        }
        eventsBound = true;

        var btnLoad = getEl("stdDashBtnLoad");
        var btnRefresh = getEl("stdDashBtnRefresh");
        var btnCloseFs = getEl("stdDashBtnCloseFullscreen");

        if (btnLoad) {
            btnLoad.addEventListener("click", loadDashboardData);
        }
        if (btnRefresh) {
            btnRefresh.addEventListener("click", function () {
                loadDashboardData();
            });
        }
        if (btnCloseFs) {
            btnCloseFs.addEventListener("click", closeFullscreen);
        }

        resetFullscreenButtons();
        var fsMap = [
            { btnId: "stdDashBtnFsMonthly", key: "monthly" },
            { btnId: "stdDashBtnFsByClass", key: "byClass" },
            { btnId: "stdDashBtnFsByScience", key: "byScience" },
            { btnId: "stdDashBtnFsByCourse", key: "byCourse" },
            { btnId: "stdDashBtnFsTrend", key: "trend" },
            { btnId: "stdDashBtnFsRatio", key: "ratio" },
            { btnId: "stdDashBtnFsBestClass", key: "bestClass" }
        ];
        var i;
        for (i = 0; i < fsMap.length; i++) {
            (function (item) {
                var btn = getEl(item.btnId);
                if (btn) {
                    btn.addEventListener("click", function () {
                        if (btn.classList.contains("std-dash-fs-btn-inactive")) {
                            return;
                        }
                        openFullscreen(item.key);
                    });
                }
            }(fsMap[i]));
        }

        document.addEventListener("keydown", function (e) {
            if (e.key === "Escape") {
                closeFullscreen();
            }
        });
    }

    function initStudentDebtDashboard() {
        bindEvents();
        loadDashboardData();
    }

    function bootStudentDebtDashboard() {
        if (document.readyState === "loading") {
            document.addEventListener("DOMContentLoaded", initStudentDebtDashboard);
        } else {
            initStudentDebtDashboard();
        }
    }

    bootStudentDebtDashboard();
}());

